/*
 * Функция flang «Приписать строку в начало».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param pervaya — «первая»: строка
 * @param elementy — «элементы»: список: строка
 * @return значение: список: строка
 */
fl_status kompilyator_flang_pripisat_stroku_v_nachalo(fl_ctx *ctx, fl_value pervaya, fl_value elementy, fl_value *result, fl_error *error) {
  fl_value fl_t1 = fl_nothing();
  FL_TRY(fl_require_list(ctx, elementy, "свёртка", &fl_t1, error));
  fl_value *fl_t2 = NULL;
  FL_TRY(fl_list_alloc(ctx, 1, &fl_t2, error));
  fl_t2[0] = pervaya;
  fl_value akk = fl_list(fl_t2, 1); /* «акк» */
  for (size_t fl_t3 = 0; fl_t3 < fl_t1.as.list.count; fl_t3 += 1) {
    const fl_value el = fl_t1.as.list.items[fl_t3]; /* «эл» */
    fl_value fl_t4 = fl_nothing(); /* «добавить» */
    FL_TRY(fl_b_dobavit(ctx, el, akk, &fl_t4, error));
    akk = fl_t4;
  }
  *result = akk;
  return FL_OK;
}

/*
 * Функция flang «Соединить строки».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param chasti — «части»: список: строка
 * @param razdelitel — «разделитель»: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_soedinit_stroki(fl_ctx *ctx, fl_value chasti, fl_value razdelitel, fl_value *result, fl_error *error) {
  if (fl_chain_empty(chasti)) {
    *result = kompilyator_flang_text_157;
    return FL_OK;
  } else if (fl_chain_cons(chasti)) {
    const fl_value golova = fl_chain_head(chasti); /* голова «голова» */
    const fl_value hvost = fl_chain_tail(chasti); /* хвост «хвост» */
    fl_value fl_t5 = fl_nothing();
    FL_TRY(fl_require_list(ctx, hvost, "свёртка", &fl_t5, error));
    fl_value akk = golova; /* «акк» */
    for (size_t fl_t6 = 0; fl_t6 < fl_t5.as.list.count; fl_t6 += 1) {
      const fl_value chast = fl_t5.as.list.items[fl_t6]; /* «часть» */
      fl_value fl_t7 = fl_nothing();
      FL_TRY(fl_concat(ctx, akk, razdelitel, &fl_t7, error));
      fl_value fl_t8 = fl_nothing();
      FL_TRY(fl_concat(ctx, fl_t7, chast, &fl_t8, error));
      akk = fl_t8;
    }
    *result = akk;
    return FL_OK;
  } else {
    return fl_match_fail(ctx, chasti, error);
  }
}

/*
 * Функция flang «Заменить».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param tekst — «текст»: строка
 * @param chto — «что»: строка
 * @param chem — «чем»: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_zamenit(fl_ctx *ctx, fl_value tekst, fl_value chto, fl_value chem, fl_value *result, fl_error *error) {
  fl_value fl_t9 = fl_nothing(); /* «разделить» */
  FL_TRY(fl_b_razdelit(ctx, tekst, chto, &fl_t9, error));
  return kompilyator_flang_soedinit_stroki(ctx, fl_t9, chem, result, error);
}

/*
 * Функция flang «Позиция подстроки».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param tekst — «текст»: строка
 * @param chast — «часть»: строка
 * @return значение: число
 */
fl_status kompilyator_flang_poziciya_podstroki(fl_ctx *ctx, fl_value tekst, fl_value chast, fl_value *result, fl_error *error) {
  fl_value fl_t10 = fl_nothing(); /* «содержит» */
  FL_TRY(fl_b_soderzhit(ctx, tekst, chast, &fl_t10, error));
  bool fl_t11 = false;
  FL_TRY(fl_cond(ctx, fl_t10, &fl_t11, error));
  if (fl_t11) {
    fl_value fl_t12 = fl_nothing(); /* «разделить» */
    FL_TRY(fl_b_razdelit(ctx, tekst, chast, &fl_t12, error));
    fl_value fl_t13 = fl_nothing(); /* «голова» */
    FL_TRY(fl_b_golova(ctx, fl_t12, &fl_t13, error));
    fl_value fl_t14 = fl_nothing(); /* «длина» */
    FL_TRY(fl_b_dlina(ctx, fl_t13, &fl_t14, error));
    fl_value fl_t15 = fl_nothing();
    FL_TRY(fl_add(ctx, fl_t14, fl_number(1.0), &fl_t15, error));
    *result = fl_t15;
    return FL_OK;
  } else {
    *result = fl_number(0.0);
    return FL_OK;
  }
}

