      fl_value fl_t8995 = fl_nothing();
      FL_TRY(fl_record_new(ctx, kompilyator_flang_names_46, fl_t8996, 2, &fl_t8995, error));
      fl_value fl_t8997 = fl_nothing(); /* «добавить» */
