/* Тело «Собрать сигнатуры»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_sobrat_signatury_body(fl_ctx *ctx, fl_value funkcii, fl_value sbor, fl_value *result, fl_error *error) {
  for (;;) {
    FL_TRY(fl_tick(ctx, "Собрать сигнатуры", error));
    if (fl_chain_empty(funkcii)) {
      *result = sbor;
      return FL_OK;
    } else if (fl_chain_cons(funkcii)) {
      const fl_value golova = fl_chain_head(funkcii); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(funkcii); /* хвост «хвост» */
      fl_value fl_t13540 = fl_nothing();
      FL_TRY(kompilyator_flang_sobrat_signaturu(ctx, golova, sbor, &fl_t13540, error));
      funkcii = hvost;
      sbor = fl_t13540;
      continue;
    } else {
      return fl_match_fail(ctx, funkcii, error);
    }
  }
}

