    const fl_value golova = fl_chain_head(parametry); /* голова «голова» */
    const fl_value hvost = fl_chain_tail(parametry); /* хвост «хвост» */
    /* хвостовой вызов «Собрать параметр» — отскок, а не кадр стека */
    bounce->args[0] = golova;
    bounce->args[1] = hvost;
    bounce->args[2] = gotovye;
